-- TMDB-MOVIE-PREPROCESS-066: dry run of process 75 step 1 after the audit of 2026-10-21
-- (1.1.24), movies and series, the SELECT its INSERT reads, generated from
-- f_buildworkfinancetable(). READ ONLY. Materialised once in a temporary table, then read
-- by the sections below.
--   A. rows, distinct statements (A > distinct = a Q-id shared by several works, the rows
--      1.1.22 lost), places, dates by role;
--   B. dates by precision and role, converted or left NULL;
--   C. statements whose first pick hides other places or points in time;
--   D. witnesses Avatar (Q24871) and Inception (Q25188), as in the dry run of 2026-10-20.

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TEMPORARY TABLE tmp_dry_066 AS
SELECT s.ID_STATEMENT, 'movie' AS ITEM_TYPE, w.ID_MOVIE AS ID_ITEM, s.ID_WIKIDATA,
       IF(s.ID_PROPERTY = 'P2130', 'budget', 'box_office') AS FINANCE_KIND,
       q.AMOUNT, q.UNIT_ID_WIKIDATA AS ID_CURRENCY, CASE q.UNIT_ID_WIKIDATA WHEN 'Q4917' THEN 'USD' WHEN 'Q4916' THEN 'EUR' WHEN 'Q25224' THEN 'GBP' WHEN 'Q8146' THEN 'JPY' WHEN 'Q41044' THEN 'RUB' WHEN 'Q1104069' THEN 'CAD' WHEN 'Q259502' THEN 'AUD' WHEN 'Q39099' THEN 'CNY' END AS CURRENCY_CODE,
       COALESCE((SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P3005' AND sq.VALUE_TYPE = 'item' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1), (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P17' AND sq.VALUE_TYPE = 'item' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1), (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P1001' AND sq.VALUE_TYPE = 'item' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1), (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P276' AND sq.VALUE_TYPE = 'item' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1), (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P291' AND sq.VALUE_TYPE = 'item' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1)) AS ID_PLACE_WIKIDATA,
       (SELECT COUNT(*) FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY IN ('P3005', 'P17', 'P1001', 'P276', 'P291') AND sq.VALUE_TYPE = 'item') AS N_PLACES,
       (SELECT CASE WHEN qv.TIME_PRECISION IN (9, 10, 11) AND qv.YEAR_VALUE BETWEEN 1000 AND 9999 AND SUBSTRING_INDEX(qv.CALENDAR_MODEL, '/', -1) = 'Q1985727' AND COALESCE(qv.TIMEZONE_OFFSET, 0) = 0 AND (qv.TIME_PRECISION = 9 OR qv.MONTH_VALUE BETWEEN 1 AND 12) AND (qv.TIME_PRECISION < 11 OR qv.DAY_VALUE BETWEEN 1 AND DAY(LAST_DAY(MAKEDATE(qv.YEAR_VALUE, 1) + INTERVAL (qv.MONTH_VALUE - 1) MONTH))) THEN MAKEDATE(qv.YEAR_VALUE, 1) + INTERVAL IF(qv.TIME_PRECISION = 9, 0, qv.MONTH_VALUE - 1) MONTH + INTERVAL IF(qv.TIME_PRECISION = 11, qv.DAY_VALUE - 1, 0) DAY END FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P585' AND sq.VALUE_TYPE = 'time' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS DAT_POINT, (SELECT qv.TIME_PRECISION FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P585' AND sq.VALUE_TYPE = 'time' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS POINT_PRECISION,
       (SELECT COUNT(*) FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY IN ('P585') AND sq.VALUE_TYPE = 'time') AS N_POINTS,
       (SELECT CASE WHEN qv.TIME_PRECISION IN (9, 10, 11) AND qv.YEAR_VALUE BETWEEN 1000 AND 9999 AND SUBSTRING_INDEX(qv.CALENDAR_MODEL, '/', -1) = 'Q1985727' AND COALESCE(qv.TIMEZONE_OFFSET, 0) = 0 AND (qv.TIME_PRECISION = 9 OR qv.MONTH_VALUE BETWEEN 1 AND 12) AND (qv.TIME_PRECISION < 11 OR qv.DAY_VALUE BETWEEN 1 AND DAY(LAST_DAY(MAKEDATE(qv.YEAR_VALUE, 1) + INTERVAL (qv.MONTH_VALUE - 1) MONTH))) THEN MAKEDATE(qv.YEAR_VALUE, 1) + INTERVAL IF(qv.TIME_PRECISION = 9, 0, qv.MONTH_VALUE - 1) MONTH + INTERVAL IF(qv.TIME_PRECISION = 11, qv.DAY_VALUE - 1, 0) DAY END FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P580' AND sq.VALUE_TYPE = 'time' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS DAT_START, (SELECT qv.TIME_PRECISION FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P580' AND sq.VALUE_TYPE = 'time' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS START_PRECISION,
       (SELECT CASE WHEN qv.TIME_PRECISION IN (9, 10, 11) AND qv.YEAR_VALUE BETWEEN 1000 AND 9999 AND SUBSTRING_INDEX(qv.CALENDAR_MODEL, '/', -1) = 'Q1985727' AND COALESCE(qv.TIMEZONE_OFFSET, 0) = 0 AND (qv.TIME_PRECISION = 9 OR qv.MONTH_VALUE BETWEEN 1 AND 12) AND (qv.TIME_PRECISION < 11 OR qv.DAY_VALUE BETWEEN 1 AND DAY(LAST_DAY(MAKEDATE(qv.YEAR_VALUE, 1) + INTERVAL (qv.MONTH_VALUE - 1) MONTH))) THEN MAKEDATE(qv.YEAR_VALUE, 1) + INTERVAL IF(qv.TIME_PRECISION = 9, 0, qv.MONTH_VALUE - 1) MONTH + INTERVAL IF(qv.TIME_PRECISION = 11, qv.DAY_VALUE - 1, 0) DAY END FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P582' AND sq.VALUE_TYPE = 'time' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS DAT_END, (SELECT qv.TIME_PRECISION FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P582' AND sq.VALUE_TYPE = 'time' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS END_PRECISION,
       (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P1264' AND sq.VALUE_TYPE = 'item' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS ID_PERIOD_WIKIDATA, (SELECT qv.AMOUNT FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_QUANTITY_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P1352' AND sq.VALUE_TYPE = 'quantity' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS CHART_RANK,
       (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P459' AND sq.VALUE_TYPE = 'item' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS ID_METHOD_WIKIDATA,
       s.`RANK` AS WIKIDATA_RANK, s.DISPLAY_ORDER
FROM T_WC_WIKIDATA_STATEMENT s
JOIN T_WC_WIKIDATA_QUANTITY_VALUE q ON q.ID_STATEMENT = s.ID_STATEMENT
JOIN `T_WC_T2S_MOVIE` w ON w.ID_WIKIDATA = s.ID_WIKIDATA AND COALESCE(w.DELETED, 0) = 0
WHERE s.ID_PROPERTY IN ('P2130', 'P2142') AND s.VALUE_TYPE = 'quantity'
  AND (s.`RANK` IS NULL OR s.`RANK` <> 'deprecated')
  AND q.AMOUNT IS NOT NULL
UNION ALL
SELECT s.ID_STATEMENT, 'serie' AS ITEM_TYPE, w.ID_SERIE AS ID_ITEM, s.ID_WIKIDATA,
       IF(s.ID_PROPERTY = 'P2130', 'budget', 'box_office') AS FINANCE_KIND,
       q.AMOUNT, q.UNIT_ID_WIKIDATA AS ID_CURRENCY, CASE q.UNIT_ID_WIKIDATA WHEN 'Q4917' THEN 'USD' WHEN 'Q4916' THEN 'EUR' WHEN 'Q25224' THEN 'GBP' WHEN 'Q8146' THEN 'JPY' WHEN 'Q41044' THEN 'RUB' WHEN 'Q1104069' THEN 'CAD' WHEN 'Q259502' THEN 'AUD' WHEN 'Q39099' THEN 'CNY' END AS CURRENCY_CODE,
       COALESCE((SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P3005' AND sq.VALUE_TYPE = 'item' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1), (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P17' AND sq.VALUE_TYPE = 'item' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1), (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P1001' AND sq.VALUE_TYPE = 'item' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1), (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P276' AND sq.VALUE_TYPE = 'item' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1), (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P291' AND sq.VALUE_TYPE = 'item' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1)) AS ID_PLACE_WIKIDATA,
       (SELECT COUNT(*) FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY IN ('P3005', 'P17', 'P1001', 'P276', 'P291') AND sq.VALUE_TYPE = 'item') AS N_PLACES,
       (SELECT CASE WHEN qv.TIME_PRECISION IN (9, 10, 11) AND qv.YEAR_VALUE BETWEEN 1000 AND 9999 AND SUBSTRING_INDEX(qv.CALENDAR_MODEL, '/', -1) = 'Q1985727' AND COALESCE(qv.TIMEZONE_OFFSET, 0) = 0 AND (qv.TIME_PRECISION = 9 OR qv.MONTH_VALUE BETWEEN 1 AND 12) AND (qv.TIME_PRECISION < 11 OR qv.DAY_VALUE BETWEEN 1 AND DAY(LAST_DAY(MAKEDATE(qv.YEAR_VALUE, 1) + INTERVAL (qv.MONTH_VALUE - 1) MONTH))) THEN MAKEDATE(qv.YEAR_VALUE, 1) + INTERVAL IF(qv.TIME_PRECISION = 9, 0, qv.MONTH_VALUE - 1) MONTH + INTERVAL IF(qv.TIME_PRECISION = 11, qv.DAY_VALUE - 1, 0) DAY END FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P585' AND sq.VALUE_TYPE = 'time' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS DAT_POINT, (SELECT qv.TIME_PRECISION FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P585' AND sq.VALUE_TYPE = 'time' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS POINT_PRECISION,
       (SELECT COUNT(*) FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY IN ('P585') AND sq.VALUE_TYPE = 'time') AS N_POINTS,
       (SELECT CASE WHEN qv.TIME_PRECISION IN (9, 10, 11) AND qv.YEAR_VALUE BETWEEN 1000 AND 9999 AND SUBSTRING_INDEX(qv.CALENDAR_MODEL, '/', -1) = 'Q1985727' AND COALESCE(qv.TIMEZONE_OFFSET, 0) = 0 AND (qv.TIME_PRECISION = 9 OR qv.MONTH_VALUE BETWEEN 1 AND 12) AND (qv.TIME_PRECISION < 11 OR qv.DAY_VALUE BETWEEN 1 AND DAY(LAST_DAY(MAKEDATE(qv.YEAR_VALUE, 1) + INTERVAL (qv.MONTH_VALUE - 1) MONTH))) THEN MAKEDATE(qv.YEAR_VALUE, 1) + INTERVAL IF(qv.TIME_PRECISION = 9, 0, qv.MONTH_VALUE - 1) MONTH + INTERVAL IF(qv.TIME_PRECISION = 11, qv.DAY_VALUE - 1, 0) DAY END FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P580' AND sq.VALUE_TYPE = 'time' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS DAT_START, (SELECT qv.TIME_PRECISION FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P580' AND sq.VALUE_TYPE = 'time' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS START_PRECISION,
       (SELECT CASE WHEN qv.TIME_PRECISION IN (9, 10, 11) AND qv.YEAR_VALUE BETWEEN 1000 AND 9999 AND SUBSTRING_INDEX(qv.CALENDAR_MODEL, '/', -1) = 'Q1985727' AND COALESCE(qv.TIMEZONE_OFFSET, 0) = 0 AND (qv.TIME_PRECISION = 9 OR qv.MONTH_VALUE BETWEEN 1 AND 12) AND (qv.TIME_PRECISION < 11 OR qv.DAY_VALUE BETWEEN 1 AND DAY(LAST_DAY(MAKEDATE(qv.YEAR_VALUE, 1) + INTERVAL (qv.MONTH_VALUE - 1) MONTH))) THEN MAKEDATE(qv.YEAR_VALUE, 1) + INTERVAL IF(qv.TIME_PRECISION = 9, 0, qv.MONTH_VALUE - 1) MONTH + INTERVAL IF(qv.TIME_PRECISION = 11, qv.DAY_VALUE - 1, 0) DAY END FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P582' AND sq.VALUE_TYPE = 'time' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS DAT_END, (SELECT qv.TIME_PRECISION FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P582' AND sq.VALUE_TYPE = 'time' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS END_PRECISION,
       (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P1264' AND sq.VALUE_TYPE = 'item' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS ID_PERIOD_WIKIDATA, (SELECT qv.AMOUNT FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_QUANTITY_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P1352' AND sq.VALUE_TYPE = 'quantity' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS CHART_RANK,
       (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P459' AND sq.VALUE_TYPE = 'item' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS ID_METHOD_WIKIDATA,
       s.`RANK` AS WIKIDATA_RANK, s.DISPLAY_ORDER
FROM T_WC_WIKIDATA_STATEMENT s
JOIN T_WC_WIKIDATA_QUANTITY_VALUE q ON q.ID_STATEMENT = s.ID_STATEMENT
JOIN `T_WC_T2S_SERIE` w ON w.ID_WIKIDATA = s.ID_WIKIDATA AND COALESCE(w.DELETED, 0) = 0
WHERE s.ID_PROPERTY IN ('P2130', 'P2142') AND s.VALUE_TYPE = 'quantity'
  AND (s.`RANK` IS NULL OR s.`RANK` <> 'deprecated')
  AND q.AMOUNT IS NOT NULL;

-- A. Rows and coverage
SELECT ITEM_TYPE, COUNT(*) AS ROWS_, COUNT(DISTINCT ID_STATEMENT) AS STATEMENTS,
       SUM(FINANCE_KIND = 'budget') AS BUDGET, SUM(ID_PLACE_WIKIDATA IS NOT NULL) AS WITH_PLACE,
       SUM(DAT_POINT IS NOT NULL) AS WITH_POINT, SUM(DAT_START IS NOT NULL) AS WITH_START, SUM(DAT_END IS NOT NULL) AS WITH_END,
       SUM(CURRENCY_CODE IS NULL) AS NO_ISO_CODE
FROM tmp_dry_066 GROUP BY ITEM_TYPE;

-- A2. The Q-ids shared by several works
SELECT ID_WIKIDATA, COUNT(DISTINCT CONCAT(ITEM_TYPE, ':', ID_ITEM)) AS WORKS,
       GROUP_CONCAT(DISTINCT CONCAT(ITEM_TYPE, ':', ID_ITEM)) AS WORK_IDS, COUNT(*) AS ROWS_
FROM tmp_dry_066 GROUP BY ID_WIKIDATA HAVING WORKS > 1 ORDER BY WORKS DESC, ID_WIKIDATA LIMIT 50;

-- B. Dates by role and precision: precision set but date NULL = left out by the contract
SELECT 'P585' AS ROLE, POINT_PRECISION AS PRECISION_, COUNT(*) AS ROWS_, SUM(DAT_POINT IS NOT NULL) AS CONVERTED FROM tmp_dry_066 WHERE POINT_PRECISION IS NOT NULL GROUP BY POINT_PRECISION
UNION ALL
SELECT 'P580', START_PRECISION, COUNT(*), SUM(DAT_START IS NOT NULL) FROM tmp_dry_066 WHERE START_PRECISION IS NOT NULL GROUP BY START_PRECISION
UNION ALL
SELECT 'P582', END_PRECISION, COUNT(*), SUM(DAT_END IS NOT NULL) FROM tmp_dry_066 WHERE END_PRECISION IS NOT NULL GROUP BY END_PRECISION
ORDER BY 1, 2;

-- C. Several places or points in time on one statement
SELECT N_PLACES, N_POINTS, COUNT(*) AS ROWS_ FROM tmp_dry_066
WHERE N_PLACES > 1 OR N_POINTS > 1 GROUP BY N_PLACES, N_POINTS ORDER BY N_PLACES, N_POINTS;

-- D. Witnesses
SELECT ID_WIKIDATA, ITEM_TYPE, ID_ITEM, FINANCE_KIND, AMOUNT, CURRENCY_CODE, ID_PLACE_WIKIDATA, N_PLACES,
       DAT_POINT, POINT_PRECISION, N_POINTS, DAT_START, START_PRECISION, DAT_END, END_PRECISION, WIKIDATA_RANK
FROM tmp_dry_066 WHERE ID_WIKIDATA IN ('Q24871', 'Q25188')
ORDER BY ID_WIKIDATA, FINANCE_KIND, AMOUNT DESC;

DROP TEMPORARY TABLE tmp_dry_066;
